// Assemble the app-facing schema; English ingredient lines stay parser-ready.
function mk(s) {
  const ingredients = {};
  LANGS.forEach(l => {
    ingredients[l] = s.ing.map(it => {
      const qty = it.q != null ? String(it.q) : '';
      const unit = it.u ? unitStr(it.u, it.q, l) : '';
      return [qty, unit, it.n[l] || it.n.en].filter(Boolean).join(' ');
    });
  });
  return {
    id: s.id, name: s.name, origin: RO_ORIGIN, category: CAT,
    servings: s.servings, time: { prepMin: s.prep, cookMin: s.cook },
    costRon: s.costRon, nutrition: s.nut, tags: s.tags,
    ingredients, howIsMade: s.steps,
  };
}

const SPECS = [
  { id:'budget_001', name:NAMES.ciorba, servings:2, prep:15, cook:70, costRon:5, nut:{cal:320,prot:16,carb:50,fat:6,fib:14}, tags:['budget','vegan','healthy'],
    ing:[ {q:200,u:'g',n:I.whiteBeans}, {q:1,n:I.onion}, {q:1,n:I.carrot}, {q:100,u:'g',n:I.celery}, {q:2,u:'tbsp',n:I.oil}, {q:1,u:'tsp',n:I.paprika}, {q:2,u:'tbsp',n:I.passata}, {q:1,n:I.bayLeaf}, {q:1.5,u:'l',n:I.water}, {q:1,n:I.lemon}, {q:2,u:'tbsp',n:I.parsley}, {n:I.salt} ],
    steps:{
      ro:'Dacă folosești fasole uscată, las-o peste noapte în apă rece, apoi scurge-o. Pune fasolea într-o oală mare cu apă proaspătă, dă în clocot, ia spuma cu o lingură și fierbe circa 45 de minute, până e aproape moale. Între timp, toacă mărunt ceapa, morcovul și țelina și călește-le în ulei 5 minute, apoi adaugă boiaua și roșiile pasate și mai gătește 2 minute. Pune această bază peste fasole împreună cu foaia de dafin și un praf bun de sare și fierbe încă 20 de minute, până fasolea e moale, iar ciorba prinde corp. Acrește după gust cu zeamă de lămâie — asta o face „ciorbă" — și potrivește sarea. Presară pătrunjel tocat și servește fierbinte, cu pâine.',
      en:'If using dried beans, soak them overnight in cold water, then drain. Put the beans in a large pot with fresh water, bring to a boil, skim off the foam, and simmer for about 45 minutes until nearly tender. Meanwhile, finely chop the onion, carrot and celery and soften them in the oil for 5 minutes, then stir in the paprika and tomato passata and cook for 2 more minutes. Add this base to the beans with the bay leaf and a good pinch of salt, and simmer for another 20 minutes, until the beans are soft and the soup has body. Sour it to taste with a squeeze of lemon — this is what makes it a ciorbă — and adjust the salt. Scatter over the chopped parsley and serve hot with bread.',
      es:'Si usas alubias secas, remójalas toda la noche en agua fría y escúrrelas. Ponlas en una olla grande con agua limpia, lleva a ebullición, retira la espuma y cuece unos 45 minutos hasta que estén casi tiernas. Mientras, pica fino la cebolla, la zanahoria y el apio y sofríelos en el aceite 5 minutos, luego añade el pimentón y el tomate y cocina 2 minutos más. Agrega esta base a las alubias con la hoja de laurel y una buena pizca de sal, y cuece otros 20 minutos, hasta que estén blandas y la sopa tenga cuerpo. Acidúlala al gusto con un chorro de limón —eso la convierte en ciorbă— y ajusta la sal. Espolvorea el perejil picado y sirve caliente con pan.',
      fr:'Si vous utilisez des haricots secs, faites-les tremper une nuit à l’eau froide, puis égouttez. Mettez-les dans une grande casserole d’eau fraîche, portez à ébullition, écumez et laissez mijoter environ 45 minutes jusqu’à ce qu’ils soient presque tendres. Pendant ce temps, hachez finement l’oignon, la carotte et le céleri et faites-les revenir dans l’huile 5 minutes, puis ajoutez le paprika et les tomates passées et poursuivez 2 minutes. Ajoutez cette base aux haricots avec la feuille de laurier et une bonne pincée de sel, et laissez mijoter encore 20 minutes, jusqu’à ce que les haricots soient tendres et la soupe ait du corps. Acidulez au goût d’un filet de citron — c’est ce qui en fait une ciorbă — et rectifiez le sel. Parsemez de persil haché et servez chaud avec du pain.',
      de:'Bei getrockneten Bohnen diese über Nacht in kaltem Wasser einweichen und abgießen. Die Bohnen mit frischem Wasser in einen großen Topf geben, aufkochen, den Schaum abschöpfen und etwa 45 Minuten köcheln, bis sie fast weich sind. Währenddessen Zwiebel, Karotte und Sellerie fein hacken und im Öl 5 Minuten anschwitzen, dann Paprikapulver und passierte Tomaten einrühren und 2 Minuten weiterkochen. Diese Basis mit dem Lorbeerblatt und einer guten Prise Salz zu den Bohnen geben und weitere 20 Minuten köcheln, bis die Bohnen weich sind und die Suppe Körper hat. Nach Geschmack mit einem Spritzer Zitrone säuern — das macht sie zur Ciorbă — und salzen. Mit gehackter Petersilie bestreuen und heiß mit Brot servieren.',
      pt:'Se usar feijão seco, demolhe-o de um dia para o outro em água fria e escorra. Coloque o feijão numa panela grande com água fresca, deixe ferver, retire a espuma e cozinhe cerca de 45 minutos até ficar quase macio. Entretanto, pique fino a cebola, a cenoura e o aipo e refogue no óleo 5 minutos, depois junte o colorau e o tomate passata e cozinhe mais 2 minutos. Junte esta base ao feijão com a folha de louro e uma boa pitada de sal, e cozinhe mais 20 minutos, até o feijão ficar macio e a sopa ganhar corpo. Acidule a gosto com sumo de limão — é o que a torna uma ciorbă — e acerte o sal. Polvilhe com salsa picada e sirva quente com pão.',
      ru:'Если используете сухую фасоль, замочите её на ночь в холодной воде и слейте. Положите фасоль в большую кастрюлю со свежей водой, доведите до кипения, снимите пену и варите около 45 минут почти до мягкости. Тем временем мелко нарежьте лук, морковь и сельдерей и обжарьте в масле 5 минут, затем вмешайте паприку и протёртые томаты и готовьте ещё 2 минуты. Добавьте эту основу к фасоли с лавровым листом и хорошей щепоткой соли и варите ещё 20 минут, пока фасоль не станет мягкой, а суп — насыщенным. Подкислите по вкусу соком лимона — именно это делает его чорбой — и посолите. Посыпьте рубленой петрушкой и подавайте горячим с хлебом.',
      ar:'إن استخدمت الفاصوليا الجافة، انقعها ليلة كاملة في ماء بارد ثم صفّها. ضع الفاصوليا في قدر كبير مع ماء جديد، اغلها وأزل الرغوة، واطهها نحو 45 دقيقة حتى تقترب من النضج. في هذه الأثناء افرم البصل والجزر والكرفس ناعماً وشوّحها في الزيت 5 دقائق، ثم أضف البابريكا والطماطم المهروسة واطهها دقيقتين إضافيتين. أضف هذا الأساس إلى الفاصوليا مع ورقة الغار ورشة ملح جيدة، واطهها 20 دقيقة أخرى حتى تلين الفاصوليا وتكتسب الشوربة قواماً. حمّضها حسب الذوق بعصير الليمون — وهذا ما يجعلها «تشوربا» — واضبط الملح. انثر البقدونس المفروم وقدّمها ساخنة مع الخبز.',
      zh:'若用干豆，先用冷水浸泡一夜后沥干。把豆子放入大锅加清水煮开，撇去浮沫，小火煮约45分钟至将熟。同时把洋葱、胡萝卜和芹菜切碎，用油炒5分钟，加入红椒粉和番茄泥再炒2分钟。将这个底料连同香叶和一大撮盐一起倒入豆子中，再煮20分钟，至豆软、汤浓。按口味挤入柠檬汁增酸——这正是它成为“酸汤（ciorbă）”的关键——再调盐。撒上切碎的欧芹，趁热配面包食用。',
      ja:'乾燥豆を使う場合は一晩冷水に浸してから水を切る。豆を大きめの鍋に入れて新しい水を注ぎ、沸騰させてアクを取り、約45分ほぼ柔らかくなるまで煮る。その間に玉ねぎ、にんじん、セロリをみじん切りにして油で5分炒め、パプリカとトマトピューレを加えてさらに2分炒める。このベースを豆にローリエと塩ひとつまみとともに加え、さらに20分、豆が柔らかくスープにコクが出るまで煮る。好みでレモンを搾って酸味をつける——これが「チョルバ」たるゆえん——塩で調える。刻んだパセリを散らし、パンを添えて熱いうちに供する。',
      hi:'सूखी बीन्स इस्तेमाल कर रहे हों तो रातभर ठंडे पानी में भिगोकर छान लें। बीन्स को बड़े बर्तन में ताज़े पानी के साथ डालकर उबालें, झाग हटाएँ और लगभग 45 मिनट लगभग नरम होने तक पकाएँ। इस बीच प्याज़, गाजर और सेलेरी बारीक काटकर तेल में 5 मिनट भूनें, फिर पेपरिका और टमाटर प्यूरी डालकर 2 मिनट और पकाएँ। यह बेस बीन्स में तेज पत्ता और अच्छी चुटकी नमक के साथ डालें और 20 मिनट और पकाएँ, जब तक बीन्स नरम और सूप गाढ़ा हो। स्वादानुसार नींबू निचोड़कर खट्टा करें — यही इसे „चोरबा" बनाता है — और नमक ठीक करें। कटा हरा धनिया छिड़कें और ब्रेड के साथ गरम परोसें।',
      tr:'Kuru fasulye kullanıyorsanız gece boyu soğuk suda ıslatıp süzün. Fasulyeyi büyük bir tencerede taze suyla kaynatın, köpüğünü alın ve neredeyse yumuşayana dek yaklaşık 45 dakika pişirin. Bu sırada soğan, havuç ve kerevizi ince doğrayıp yağda 5 dakika kavurun, sonra toz biberi ve domates püresini ekleyip 2 dakika daha pişirin. Bu harcı defne yaprağı ve iyi bir tutam tuzla fasulyeye ekleyin ve fasulye yumuşayıp çorba kıvam alana dek 20 dakika daha pişirin. Damak tadınıza göre limon sıkarak ekşitin — onu „çorba" yapan budur — ve tuzu ayarlayın. Kıyılmış maydanoz serpip ekmekle sıcak servis edin.',
      it:'Se usi fagioli secchi, mettili in ammollo una notte in acqua fredda, poi scola. Metti i fagioli in una pentola capiente con acqua fresca, porta a bollore, schiuma e fai sobbollire circa 45 minuti finché sono quasi teneri. Intanto trita fine cipolla, carota e sedano e falli appassire nell’olio 5 minuti, poi unisci la paprica e la passata e cuoci altri 2 minuti. Aggiungi questa base ai fagioli con l’alloro e una buona presa di sale, e fai sobbollire altri 20 minuti, finché i fagioli sono morbidi e la zuppa ha corpo. Acidula a piacere con una spremuta di limone — è ciò che la rende una ciorbă — e regola il sale. Cospargi di prezzemolo tritato e servi calda con pane.',
      ko:'말린 콩을 쓰면 찬물에 하룻밤 불린 뒤 물을 뺀다. 콩을 큰 냄비에 새 물과 함께 넣고 끓여 거품을 걷어내고 약 45분간 거의 익을 때까지 끓인다. 그동안 양파, 당근, 셀러리를 곱게 다져 기름에 5분 볶고 파프리카 가루와 토마토 퓌레를 넣어 2분 더 볶는다. 이 베이스를 월계수 잎, 소금 넉넉히 한 꼬집과 함께 콩에 넣고 콩이 부드러워지고 국물에 깊이가 생길 때까지 20분 더 끓인다. 기호대로 레몬을 짜 신맛을 낸다 — 이것이 „초르버"를 만드는 핵심이다 — 소금으로 간한다. 다진 파슬리를 뿌려 빵과 함께 뜨겁게 낸다.' } },

  { id:'budget_002', name:NAMES.tocanita, servings:2, prep:10, cook:30, costRon:3, nut:{cal:350,prot:7,carb:60,fat:10,fib:6}, tags:['budget','vegan','one-pot'],
    ing:[ {q:600,u:'g',n:I.potatoes}, {q:1,n:I.onion}, {q:2,u:'tbsp',n:I.oil}, {q:1,u:'tsp',n:I.paprika}, {q:2,u:'clove',n:I.garlic}, {q:150,u:'g',n:I.passata}, {q:1,n:I.bayLeaf}, {q:300,u:'ml',n:I.water}, {n:I.salt} ],
    steps:{
      ro:'Curăță cartofii și taie-i cuburi de o îmbucătură. Încălzește uleiul într-o oală și călește ceapa tocată la foc mediu 5 minute, până se înmoaie și se rumenește. Adaugă boiaua și usturoiul și amestecă 30 de secunde — nu lăsa boiaua să ardă, că amărăște — apoi pune roșiile pasate și foaia de dafin. Adaugă cartofii, apa și un praf bun de sare, amestecă să se acopere, apoi fierbe acoperit, la foc mic, circa 25 de minute, până cartofii sunt fragezi și sosul s-a legat. Scutură oala din când în când în loc să amesteci tare, ca să rămână cartofii întregi. Servește fierbinte, simplu sau cu o lingură de smântână, dacă ai.',
      en:'Peel the potatoes and cut them into bite-sized chunks. Warm the oil in a pot and cook the chopped onion over medium heat for 5 minutes, until soft and golden. Stir in the paprika and garlic and cook for 30 seconds — don’t let the paprika burn or it turns bitter — then add the tomato passata and bay leaf. Add the potatoes, water and a good pinch of salt, stir to coat, then simmer covered over low heat for about 25 minutes, until the potatoes are tender and the sauce has thickened. Shake the pot now and then rather than stirring hard, so the potatoes stay whole. Serve hot, on its own or with a spoon of soured cream if you have it.',
      es:'Pela las patatas y córtalas en trozos de un bocado. Calienta el aceite en una olla y sofríe la cebolla picada a fuego medio 5 minutos, hasta que esté blanda y dorada. Añade el pimentón y el ajo y remueve 30 segundos —no dejes que el pimentón se queme o amarga— luego incorpora el tomate y la hoja de laurel. Añade las patatas, el agua y una buena pizca de sal, remueve para cubrir y cuece tapado a fuego bajo unos 25 minutos, hasta que las patatas estén tiernas y la salsa haya espesado. Agita la olla de vez en cuando en lugar de remover fuerte, para que las patatas queden enteras. Sirve caliente, solo o con una cucharada de nata agria si tienes.',
      fr:'Épluchez les pommes de terre et coupez-les en morceaux d’une bouchée. Chauffez l’huile dans une casserole et faites revenir l’oignon haché à feu moyen 5 minutes, jusqu’à ce qu’il soit tendre et doré. Ajoutez le paprika et l’ail et remuez 30 secondes — sans laisser brûler le paprika, sinon il devient amer — puis ajoutez les tomates passées et la feuille de laurier. Ajoutez les pommes de terre, l’eau et une bonne pincée de sel, mélangez pour enrober, puis laissez mijoter à couvert à feu doux environ 25 minutes, jusqu’à ce que les pommes de terre soient tendres et la sauce épaissie. Secouez la casserole de temps en temps plutôt que de remuer fort, pour garder les pommes de terre entières. Servez chaud, seul ou avec une cuillerée de crème aigre si vous en avez.',
      de:'Die Kartoffeln schälen und in mundgerechte Stücke schneiden. Das Öl in einem Topf erwärmen und die gehackte Zwiebel bei mittlerer Hitze 5 Minuten anschwitzen, bis sie weich und goldbraun ist. Paprikapulver und Knoblauch einrühren und 30 Sekunden anrösten — das Paprikapulver nicht verbrennen lassen, sonst wird es bitter — dann passierte Tomaten und Lorbeerblatt zugeben. Kartoffeln, Wasser und eine gute Prise Salz zugeben, umrühren, dann zugedeckt bei niedriger Hitze etwa 25 Minuten köcheln, bis die Kartoffeln weich sind und die Soße gebunden ist. Den Topf ab und zu schwenken statt kräftig zu rühren, damit die Kartoffeln ganz bleiben. Heiß servieren, pur oder mit einem Löffel Schmand, falls vorhanden.',
      pt:'Descasque as batatas e corte-as em pedaços de uma dentada. Aqueça o óleo numa panela e refogue a cebola picada em lume médio 5 minutos, até ficar macia e dourada. Junte o colorau e o alho e mexa 30 segundos — não deixe o colorau queimar, senão amarga — depois adicione o tomate passata e a folha de louro. Junte as batatas, a água e uma boa pitada de sal, mexa para envolver e cozinhe tapado em lume brando cerca de 25 minutos, até as batatas ficarem macias e o molho engrossar. Abane a panela de vez em quando em vez de mexer com força, para as batatas ficarem inteiras. Sirva quente, simples ou com uma colher de natas azedas se tiver.',
      ru:'Очистите картофель и нарежьте кусочками на один укус. Разогрейте масло в кастрюле и обжарьте нарезанный лук на среднем огне 5 минут, до мягкости и золотистости. Вмешайте паприку и чеснок и готовьте 30 секунд — не дайте паприке подгореть, иначе будет горчить — затем добавьте протёртые томаты и лавровый лист. Добавьте картофель, воду и хорошую щепотку соли, перемешайте, затем тушите под крышкой на слабом огне около 25 минут, пока картофель не станет мягким, а соус не загустеет. Время от времени встряхивайте кастрюлю вместо энергичного помешивания, чтобы картофель остался целым. Подавайте горячим, сам по себе или с ложкой сметаны, если есть.',
      ar:'قشّر البطاطس وقطّعها مكعبات بحجم اللقمة. سخّن الزيت في قدر وشوّح البصل المفروم على نار متوسطة 5 دقائق حتى يلين ويكتسب لوناً ذهبياً. أضف البابريكا والثوم وقلّب 30 ثانية — دون أن تحترق البابريكا وإلا صارت مرّة — ثم أضف الطماطم المهروسة وورقة الغار. أضف البطاطس والماء ورشة ملح جيدة، قلّب حتى تتغلّف، ثم اطهها مغطاة على نار هادئة نحو 25 دقيقة حتى تنضج البطاطس وتتماسك الصلصة. هزّ القدر بين الحين والآخر بدل التقليب القوي كي تبقى البطاطس كاملة. قدّمها ساخنة، وحدها أو مع ملعقة قشدة حامضة إن توفّرت.',
      zh:'土豆去皮，切成一口大小的块。锅中热油，中火炒切碎的洋葱5分钟，至变软金黄。加入红椒粉和蒜炒30秒——别让红椒粉烧焦，否则发苦——再加入番茄泥和香叶。放入土豆、水和一大撮盐，翻拌均匀，然后加盖小火煮约25分钟，至土豆软、汤汁收浓。中途晃动锅子而不要用力翻搅，让土豆保持完整。趁热食用，可单吃或加一勺酸奶油。',
      ja:'じゃがいもの皮をむき、一口大に切る。鍋に油を温め、みじん切りの玉ねぎを中火で5分、柔らかく色づくまで炒める。パプリカとにんにくを加えて30秒炒め——パプリカは焦がすと苦くなるので注意——トマトピューレとローリエを加える。じゃがいも、水、塩ひとつまみを入れて全体を混ぜ、ふたをして弱火で約25分、じゃがいもが柔らかくソースがまとまるまで煮る。強くかき混ぜず時々鍋をゆすって、じゃがいもを崩さないようにする。そのまま、あるいはあればサワークリームを添えて熱いうちに供する。',
      hi:'आलू छीलकर एक-निवाले के टुकड़ों में काटें। बर्तन में तेल गरम करें और कटा प्याज़ मध्यम आँच पर 5 मिनट नरम-सुनहरा होने तक भूनें। पेपरिका और लहसुन डालकर 30 सेकंड चलाएँ — पेपरिका जलने न दें वरना कड़वी हो जाती है — फिर टमाटर प्यूरी और तेज पत्ता डालें। आलू, पानी और अच्छी चुटकी नमक डालें, लपेटने के लिए मिलाएँ, फिर ढककर धीमी आँच पर लगभग 25 मिनट पकाएँ जब तक आलू नरम और सॉस गाढ़ी हो। तेज़ चलाने के बजाय बीच-बीच में बर्तन हिलाएँ ताकि आलू साबुत रहें। गरम, अकेले या एक चम्मच खट्टी क्रीम के साथ परोसें।',
      tr:'Patatesleri soyup lokma büyüklüğünde doğrayın. Tencerede yağı ısıtın ve doğranmış soğanı orta ateşte 5 dakika, yumuşayıp kızarana dek kavurun. Toz biber ve sarımsağı ekleyip 30 saniye karıştırın — toz biberi yakmayın, yoksa acılaşır — sonra domates püresi ve defne yaprağını ekleyin. Patatesleri, suyu ve iyi bir tutam tuzu ekleyip harmanlayın, ardından kapağını kapatıp kısık ateşte yaklaşık 25 dakika, patatesler yumuşayıp sos koyulaşana dek pişirin. Sert karıştırmak yerine ara sıra tencereyi sallayın ki patatesler bütün kalsın. Sıcak, tek başına ya da varsa bir kaşık ekşi krema ile servis edin.',
      it:'Sbuccia le patate e tagliale a pezzi di un boccone. Scalda l’olio in una pentola e rosola la cipolla tritata a fuoco medio per 5 minuti, finché è morbida e dorata. Unisci la paprica e l’aglio e mescola 30 secondi — non far bruciare la paprica, o diventa amara — poi aggiungi la passata e l’alloro. Aggiungi le patate, l’acqua e una buona presa di sale, mescola per insaporire, poi cuoci coperto a fuoco basso circa 25 minuti, finché le patate sono tenere e il sugo si è addensato. Scuoti la pentola ogni tanto invece di mescolare con forza, così le patate restano intere. Servi caldo, da solo o con un cucchiaio di panna acida se ce l’hai.',
      ko:'감자는 껍질을 벗겨 한입 크기로 썬다. 냄비에 기름을 데우고 다진 양파를 중불에서 5분간 부드럽고 노릇해질 때까지 볶는다. 파프리카 가루와 마늘을 넣고 30초 볶는다 — 파프리카는 태우면 쓴맛이 나니 주의 — 토마토 퓌레와 월계수 잎을 넣는다. 감자, 물, 소금 넉넉히 한 꼬집을 넣어 고루 섞은 뒤 뚜껑을 덮어 약불에서 약 25분간 감자가 부드럽고 소스가 걸쭉해질 때까지 끓인다. 세게 젓지 말고 가끔 냄비를 흔들어 감자가 부서지지 않게 한다. 그대로 또는 있으면 사워크림 한 숟갈과 함께 뜨겁게 낸다.' } },

  { id:'budget_003', name:NAMES.iahnie, servings:2, prep:10, cook:25, costRon:4, nut:{cal:340,prot:16,carb:48,fat:9,fib:13}, tags:['budget','vegan','high-protein'],
    ing:[ {q:400,u:'g',n:I.beans}, {q:1,n:I.onion}, {q:2,u:'tbsp',n:I.oil}, {q:2,u:'clove',n:I.garlic}, {q:1,u:'tsp',n:I.paprika}, {q:150,u:'g',n:I.passata}, {q:1,n:I.bayLeaf}, {n:I.salt} ],
    steps:{
      ro:'Încălzește uleiul într-o oală și călește ceapa tocată mărunt la foc mediu circa 6 minute, până se înmoaie și se rumenește frumos — o ceapă bine gătită e sufletul acestui fel. Adaugă usturoiul și boiaua și amestecă 30 de secunde, apoi pune roșiile pasate și foaia de dafin și lasă să dea în clocot 3 minute. Scurge și clătește fasolea, adaug-o în oală cu un strop de apă și fierbe blând 15 minute, ca să se pătrundă de arome. Zdrobește câteva boabe de peretele oalei ca să îngroși sosul într-o tocană cremoasă. Potrivește de sare și mai adaugă puțină apă dacă se leagă prea tare. Servește caldă, tradițional cu murături sau pâine.',
      en:'Warm the oil in a pot and cook the finely chopped onion over medium heat for about 6 minutes, until soft and nicely golden — a well-cooked onion is the backbone of this dish. Add the garlic and paprika and stir for 30 seconds, then add the tomato passata and bay leaf and let it bubble for 3 minutes. Drain and rinse the beans, add them to the pot with a splash of water, and simmer gently for 15 minutes so they take on the flavour. Mash a few beans against the side of the pot to thicken the sauce into a creamy stew. Season with salt to taste, and add a little water if it gets too thick. Serve warm, traditionally with pickles or bread.',
      es:'Calienta el aceite en una olla y sofríe la cebolla picada fina a fuego medio unos 6 minutos, hasta que esté blanda y bien dorada —una cebolla bien hecha es el alma de este plato—. Añade el ajo y el pimentón y remueve 30 segundos, luego incorpora el tomate y la hoja de laurel y deja borbotear 3 minutos. Escurre y enjuaga las alubias, añádelas con un chorrito de agua y cuece suave 15 minutos para que tomen sabor. Aplasta unas alubias contra la olla para espesar la salsa en un guiso cremoso. Sazona con sal y añade un poco de agua si queda muy espeso. Sirve caliente, tradicionalmente con encurtidos o pan.',
      fr:'Chauffez l’huile dans une casserole et faites revenir l’oignon finement haché à feu moyen environ 6 minutes, jusqu’à ce qu’il soit tendre et bien doré — un oignon bien cuit est l’âme de ce plat. Ajoutez l’ail et le paprika et remuez 30 secondes, puis ajoutez les tomates passées et la feuille de laurier et laissez bouillonner 3 minutes. Égouttez et rincez les haricots, ajoutez-les avec un peu d’eau et laissez mijoter doucement 15 minutes pour qu’ils s’imprègnent. Écrasez quelques haricots contre la casserole pour épaissir la sauce en un ragoût crémeux. Salez et ajoutez un peu d’eau si c’est trop épais. Servez chaud, traditionnellement avec des pickles ou du pain.',
      de:'Das Öl in einem Topf erwärmen und die fein gehackte Zwiebel bei mittlerer Hitze etwa 6 Minuten anschwitzen, bis sie weich und schön goldbraun ist — eine gut gegarte Zwiebel ist das Rückgrat dieses Gerichts. Knoblauch und Paprikapulver zugeben und 30 Sekunden rühren, dann passierte Tomaten und Lorbeerblatt zugeben und 3 Minuten blubbern lassen. Die Bohnen abtropfen und abspülen, mit einem Schuss Wasser in den Topf geben und 15 Minuten sanft köcheln, damit sie Geschmack aufnehmen. Ein paar Bohnen am Topfrand zerdrücken, um die Soße zu einem cremigen Eintopf zu binden. Mit Salz abschmecken und bei Bedarf etwas Wasser zugeben. Warm servieren, traditionell mit Eingelegtem oder Brot.',
      pt:'Aqueça o óleo numa panela e refogue a cebola bem picada em lume médio cerca de 6 minutos, até ficar macia e bem dourada — uma cebola bem feita é a alma deste prato. Junte o alho e o colorau e mexa 30 segundos, depois adicione o tomate passata e a folha de louro e deixe borbulhar 3 minutos. Escorra e lave o feijão, junte-o com um pouco de água e cozinhe brandamente 15 minutos para absorver o sabor. Esmague alguns grãos contra a panela para engrossar o molho num guisado cremoso. Tempere com sal e junte um pouco de água se ficar muito espesso. Sirva quente, tradicionalmente com picles ou pão.',
      ru:'Разогрейте масло в кастрюле и обжарьте мелко нарезанный лук на среднем огне около 6 минут, до мягкости и красивой золотистости — хорошо приготовленный лук основа этого блюда. Добавьте чеснок и паприку, помешивайте 30 секунд, затем добавьте протёртые томаты и лавровый лист и дайте побулькать 3 минуты. Слейте и промойте фасоль, добавьте её с небольшим количеством воды и тушите на слабом огне 15 минут, чтобы она пропиталась вкусом. Разомните несколько фасолин о стенку кастрюли, чтобы соус загустел в кремовое рагу. Посолите по вкусу и добавьте немного воды, если станет слишком густо. Подавайте тёплым, традиционно с соленьями или хлебом.',
      ar:'سخّن الزيت في قدر وشوّح البصل المفروم ناعماً على نار متوسطة نحو 6 دقائق حتى يلين ويكتسب لوناً ذهبياً جميلاً — البصل المطهو جيداً هو روح هذا الطبق. أضف الثوم والبابريكا وقلّب 30 ثانية، ثم أضف الطماطم المهروسة وورقة الغار واتركها تغلي 3 دقائق. صفّ الفاصوليا واغسلها، أضفها مع رشة ماء واطهها بهدوء 15 دقيقة لتتشرّب النكهة. اهرس بعض الحبات على جدار القدر لتكثيف الصلصة إلى يخنة كريمية. تبّل بالملح وأضف قليلاً من الماء إن ثخنت كثيراً. قدّمها دافئة، وتقليدياً مع المخللات أو الخبز.',
      zh:'锅中热油，中火炒切碎的洋葱约6分钟，至变软、金黄漂亮——炒透的洋葱是这道菜的灵魂。加入蒜和红椒粉炒30秒，再加番茄泥和香叶，煮沸3分钟。豆子沥干冲洗后连同少许水下锅，小火煮15分钟入味。用勺把几颗豆子压在锅壁上，使汤汁浓稠、口感绵密。加盐调味，太稠就加一点水。趁热食用，传统上配腌菜或面包。',
      ja:'鍋に油を温め、みじん切りの玉ねぎを中火で約6分、柔らかくきれいな飴色になるまで炒める——よく炒めた玉ねぎがこの料理の要。にんにくとパプリカを加えて30秒炒め、トマトピューレとローリエを加えて3分ふつふつ煮る。豆を水切りして洗い、水少々とともに鍋に加えて15分ほど静かに煮て味を含ませる。豆を数粒だけ鍋肌でつぶし、ソースにとろみをつけてクリーミーな煮込みにする。塩で味を調え、固くなりすぎたら水を少し足す。温かいうちに、伝統的にはピクルスやパンを添えて供する。',
      hi:'बर्तन में तेल गरम करें और बारीक कटा प्याज़ मध्यम आँच पर लगभग 6 मिनट नरम और अच्छा सुनहरा होने तक भूनें — अच्छी भुनी प्याज़ इस व्यंजन की जान है। लहसुन और पेपरिका डालकर 30 सेकंड चलाएँ, फिर टमाटर प्यूरी और तेज पत्ता डालकर 3 मिनट उबलने दें। बीन्स को छानकर धोएँ, थोड़े पानी के साथ बर्तन में डालें और 15 मिनट धीमी आँच पर पकाएँ ताकि स्वाद सोख लें। कुछ बीन्स को बर्तन की दीवार पर दबाकर मसलें ताकि सॉस गाढ़ी-मलाईदार सालन बने। नमक डालें और ज़्यादा गाढ़ा होने पर थोड़ा पानी मिलाएँ। गरम, परंपरागत रूप से अचार या ब्रेड के साथ परोसें।',
      tr:'Tencerede yağı ısıtın ve ince doğranmış soğanı orta ateşte yaklaşık 6 dakika, yumuşayıp güzelce kızarana dek kavurun — iyi kavrulmuş soğan bu yemeğin ruhudur. Sarımsak ve toz biberi ekleyip 30 saniye karıştırın, sonra domates püresi ve defne yaprağını ekleyip 3 dakika fıkırdatın. Fasulyeyi süzüp durulayın, biraz suyla tencereye ekleyin ve tadı çekmesi için 15 dakika hafifçe pişirin. Birkaç taneyi tava kenarında ezip sosu kremamsı bir yahniye dönüştürün. Tuzla tatlandırın, fazla koyulaşırsa biraz su ekleyin. Sıcak, geleneksel olarak turşu ya da ekmekle servis edin.',
      it:'Scalda l’olio in una pentola e rosola la cipolla tritata fine a fuoco medio per circa 6 minuti, finché è morbida e ben dorata — una cipolla ben cotta è l’anima di questo piatto. Unisci l’aglio e la paprica e mescola 30 secondi, poi aggiungi la passata e l’alloro e lascia sobbollire 3 minuti. Scola e sciacqua i fagioli, aggiungili con un goccio d’acqua e fai sobbollire dolcemente 15 minuti perché prendano sapore. Schiaccia qualche fagiolo contro la pentola per addensare il sugo in uno stufato cremoso. Regola di sale e aggiungi un po’ d’acqua se diventa troppo denso. Servi caldo, tradizionalmente con sottaceti o pane.',
      ko:'냄비에 기름을 데우고 곱게 다진 양파를 중불에서 약 6분간 부드럽고 먹음직스러운 갈색이 될 때까지 볶는다 — 잘 볶은 양파가 이 요리의 핵심이다. 마늘과 파프리카 가루를 넣고 30초 볶은 뒤 토마토 퓌레와 월계수 잎을 넣어 3분간 보글보글 끓인다. 콩을 헹궈 물기를 빼고 물을 조금 넣어 15분간 은근히 끓여 맛이 배게 한다. 콩 몇 알을 냄비 벽에 눌러 으깨 소스를 걸쭉하고 크리미한 스튜로 만든다. 소금으로 간하고 너무 되직하면 물을 조금 넣는다. 따뜻하게, 전통적으로 피클이나 빵과 함께 낸다.' } },

  { id:'budget_004', name:NAMES.vinete, servings:2, prep:15, cook:30, costRon:4, nut:{cal:180,prot:3,carb:12,fat:14,fib:6}, tags:['budget','vegan','healthy'],
    ing:[ {q:500,u:'g',n:I.eggplant}, {q:1,n:I.onion}, {q:3,u:'tbsp',n:I.oil}, {q:1,n:I.lemon}, {n:I.salt} ],
    steps:{
      ro:'Înțeapă vinetele de câteva ori cu furculița și coace-le întregi — pe flacără, la grătar sau în cuptor încins — întorcându-le până coaja e arsă, iar miezul complet moale, circa 25-30 de minute. Lasă-le să se răcorească puțin, apoi curăță coaja arsă și scurge miezul într-o strecurătoare câteva minute, ca să piardă zeama amară. Toacă miezul fin cu un cuțit sau o lingură de lemn (evită vasele de metal, care îl înnegresc) până devine aproape pastă. Încorporează uleiul câte puțin, ca la maioneză, până se albește și devine cremos. Adaugă ceapa tăiată foarte mărunt, sărează și dă gust cu zeamă de lămâie. Servește rece, întinsă pe pâine.',
      en:'Prick the eggplants a few times with a fork and roast them whole — over an open flame, under the grill, or in a hot oven — turning until the skin is charred and the flesh is completely soft, about 25-30 minutes. Let them cool a little, then peel off the blackened skin and drain the flesh in a sieve for a few minutes to lose its bitter juices. Chop the flesh finely with a knife or wooden spoon (avoid metal bowls, which darken it) until it is almost a paste. Beat in the oil a little at a time, as if making mayonnaise, until it turns pale and creamy. Fold in the very finely chopped onion, season with salt, and sharpen with a squeeze of lemon. Serve cool, spread on bread.',
      es:'Pincha las berenjenas varias veces con un tenedor y ásalas enteras —sobre la llama, al grill o en el horno caliente— girándolas hasta que la piel esté quemada y la pulpa completamente blanda, unos 25-30 minutos. Deja que se templen, pela la piel ennegrecida y escurre la pulpa en un colador unos minutos para que pierda los jugos amargos. Pica la pulpa fina con cuchillo o cuchara de madera (evita recipientes de metal, que la oscurecen) hasta casi hacer una pasta. Incorpora el aceite poco a poco, como una mayonesa, hasta que aclare y quede cremosa. Añade la cebolla muy picada, sazona con sal y realza con un chorro de limón. Sirve fría, untada en pan.',
      fr:'Piquez les aubergines plusieurs fois à la fourchette et faites-les rôtir entières — sur une flamme, sous le gril ou au four chaud — en les retournant jusqu’à ce que la peau soit carbonisée et la chair complètement molle, environ 25-30 minutes. Laissez tiédir, retirez la peau noircie et laissez égoutter la chair dans une passoire quelques minutes pour perdre ses sucs amers. Hachez la chair finement au couteau ou à la cuillère en bois (évitez les récipients en métal, qui la noircissent) jusqu’à obtenir presque une pâte. Incorporez l’huile petit à petit, comme une mayonnaise, jusqu’à ce que ce soit pâle et crémeux. Ajoutez l’oignon très finement haché, salez et relevez d’un filet de citron. Servez frais, tartiné sur du pain.',
      de:'Die Auberginen mehrmals mit einer Gabel einstechen und im Ganzen rösten — über offener Flamme, unter dem Grill oder im heißen Ofen — dabei wenden, bis die Haut verkohlt und das Fruchtfleisch ganz weich ist, etwa 25-30 Minuten. Etwas abkühlen lassen, dann die verkohlte Haut abziehen und das Fruchtfleisch in einem Sieb einige Minuten abtropfen lassen, damit es die bitteren Säfte verliert. Das Fruchtfleisch mit Messer oder Holzlöffel fein hacken (Metallschüsseln vermeiden, sie verfärben es) bis fast eine Paste entsteht. Das Öl nach und nach einarbeiten, wie bei Mayonnaise, bis es hell und cremig wird. Die sehr fein gehackte Zwiebel unterheben, salzen und mit einem Spritzer Zitrone abrunden. Kühl servieren, auf Brot gestrichen.',
      pt:'Pique as beringelas várias vezes com um garfo e asse-as inteiras — sobre a chama, no grelhador ou no forno quente — virando até a pele ficar queimada e a polpa completamente mole, cerca de 25-30 minutos. Deixe amornar, retire a pele queimada e escorra a polpa num coador alguns minutos para perder os sucos amargos. Pique a polpa fina com faca ou colher de pau (evite recipientes de metal, que a escurecem) até quase virar pasta. Incorpore o óleo aos poucos, como numa maionese, até clarear e ficar cremosa. Envolva a cebola bem picada, tempere com sal e avive com um pouco de sumo de limão. Sirva fria, barrada em pão.',
      ru:'Наколите баклажаны вилкой в нескольких местах и запеките целиком — на открытом огне, под грилем или в горячей духовке — переворачивая, пока кожица не обуглится, а мякоть не станет совсем мягкой, около 25-30 минут. Дайте немного остыть, снимите обугленную кожицу и дайте мякоти стечь в сите несколько минут, чтобы ушёл горький сок. Мелко порубите мякоть ножом или деревянной ложкой (избегайте металлической посуды, она её темнит) почти до пасты. Вбивайте масло понемногу, как при приготовлении майонеза, пока масса не побледнеет и не станет кремовой. Вмешайте очень мелко нарезанный лук, посолите и оживите соком лимона. Подавайте охлаждённой, намазав на хлеб.',
      ar:'اثقب الباذنجان عدة مرات بالشوكة واشوِه كاملاً — على لهب مباشر أو تحت الشواية أو في فرن ساخن — مع تقليبه حتى تتفحّم القشرة ويصبح اللبّ طرياً تماماً، نحو 25-30 دقيقة. اتركه يبرد قليلاً، ثم قشّر القشرة المحروقة وصفّ اللبّ في مصفاة دقائق ليفقد عصارته المُرّة. افرم اللبّ ناعماً بسكين أو ملعقة خشب (تجنّب أوعية المعدن التي تسوّده) حتى يقارب العجينة. أضف الزيت تدريجياً كأنك تعدّ المايونيز حتى يشحب لونه ويصبح كريمياً. أضف البصل المفروم ناعماً جداً، ملّحه وأنعشه بعصير الليمون. قدّمه بارداً مدهوناً على الخبز.',
      zh:'用叉子在茄子上戳几下，整只烤制——明火、烤架或热烤箱皆可——不时翻面，直到表皮焦黑、内里完全软烂，约25-30分钟。稍微放凉，剥去焦皮，把茄肉放漏网里沥几分钟，去掉苦水。用刀或木勺把茄肉剁细（别用金属容器，会使其发黑），几乎成泥。像做蛋黄酱一样一点点加入油，搅打至发白绵滑。拌入切得极细的洋葱，加盐调味，挤入柠檬汁提味。冷食，抹在面包上。',
      ja:'なすをフォークで数か所刺し、丸ごと焼く——直火、グリル、または高温のオーブンで——皮が真っ黒に焦げて中が完全に柔らかくなるまで、約25〜30分返しながら焼く。少し冷ましてから焦げた皮をむき、ざるで数分水切りして苦い汁を落とす。金属のボウルは色が黒くなるので避け、包丁か木べらで果肉をほぼペースト状に細かく刻む。マヨネーズを作る要領で油を少しずつ加え、白っぽくクリーミーになるまで混ぜる。ごく細かく刻んだ玉ねぎを混ぜ込み、塩で味を調え、レモンを搾って引き締める。冷やして、パンに塗って供する。',
      hi:'बैंगन में काँटे से कुछ जगह छेद करें और साबुत भूनें — खुली आँच पर, ग्रिल में या गरम ओवन में — पलटते हुए जब तक छिलका जल जाए और गूदा पूरी तरह नरम हो, लगभग 25-30 मिनट। थोड़ा ठंडा होने दें, जला छिलका उतारें और गूदे को छलनी में कुछ मिनट रखकर उसका कड़वा रस निकलने दें। गूदे को चाकू या लकड़ी के चम्मच से बारीक काटें (धातु के बर्तन से बचें, वे इसे काला कर देते हैं) जब तक लगभग पेस्ट न बने। मेयोनेज़ की तरह थोड़ा-थोड़ा तेल फेंटते हुए मिलाएँ जब तक यह हल्का और मलाईदार हो जाए। बहुत बारीक कटा प्याज़ मिलाएँ, नमक डालें और नींबू निचोड़कर स्वाद बढ़ाएँ। ठंडा, ब्रेड पर लगाकर परोसें।',
      tr:'Patlıcanları çatalla birkaç yerinden delin ve bütün halde közleyin — açık ateşte, ızgarada ya da kızgın fırında — kabuğu kömürleşip içi tamamen yumuşayana dek çevirerek, yaklaşık 25-30 dakika. Biraz soğutun, yanmış kabuğu soyun ve eti bir süzgeçte birkaç dakika süzerek acı suyunu bırakmasını sağlayın. Eti bıçak ya da tahta kaşıkla (kararttığı için metal kaplardan kaçının) neredeyse macun olana dek ince ince doğrayın. Mayonez yapar gibi yağı azar azar ekleyip çırpın; rengi açılıp kremamsı olsun. Çok ince doğranmış soğanı katın, tuzla tatlandırın ve limon sıkarak canlandırın. Soğuk, ekmeğe sürerek servis edin.',
      it:'Bucherella le melanzane con una forchetta e arrostiscile intere — su fiamma viva, sotto il grill o in forno caldo — girandole finché la buccia è bruciacchiata e la polpa del tutto morbida, circa 25-30 minuti. Falle intiepidire, togli la buccia annerita e scola la polpa in un colino qualche minuto per perdere i succhi amari. Trita la polpa fine con coltello o cucchiaio di legno (evita recipienti di metallo, che la scuriscono) fin quasi a crema. Incorpora l’olio poco alla volta, come per una maionese, finché diventa pallida e cremosa. Unisci la cipolla tritata finissima, sala e ravviva con una spremuta di limone. Servi fresca, spalmata sul pane.',
      ko:'가지를 포크로 몇 군데 찌른 뒤 통째로 굽는다 — 직화, 그릴, 또는 뜨거운 오븐에서 — 껍질이 새까맣게 타고 속이 완전히 물러질 때까지 약 25~30분 뒤집어가며 굽는다. 살짝 식힌 뒤 탄 껍질을 벗기고 과육을 체에 몇 분간 밭쳐 쓴 즙을 뺀다. 금속 그릇은 색을 검게 하니 피하고, 칼이나 나무 주걱으로 과육을 거의 페이스트가 될 때까지 곱게 다진다. 마요네즈를 만들듯 기름을 조금씩 넣어 색이 연해지고 크리미해질 때까지 젓는다. 아주 곱게 다진 양파를 섞고 소금으로 간한 뒤 레몬을 짜 맛을 살린다. 차갑게, 빵에 발라 낸다.' } },

  { id:'budget_005', name:NAMES.ghiveci, servings:2, prep:20, cook:35, costRon:5, nut:{cal:260,prot:6,carb:38,fat:10,fib:9}, tags:['budget','vegan','healthy'],
    ing:[ {q:200,u:'g',n:I.potatoes}, {q:1,n:I.carrot}, {q:1,n:I.onion}, {q:1,n:I.bellPepper}, {q:200,u:'g',n:I.zucchini}, {q:200,u:'g',n:I.passata}, {q:2,u:'clove',n:I.garlic}, {q:3,u:'tbsp',n:I.oil}, {q:1,n:I.bayLeaf}, {n:I.salt} ],
    steps:{
      ro:'Taie toate legumele — cartof, morcov, ceapă, ardei gras și dovlecel — în bucăți de mărime asemănătoare, ca să se gătească uniform. Încălzește uleiul într-o oală largă și călește ceapa și usturoiul 4 minute, apoi adaugă legumele mai tari (cartof și morcov) și mai gătește 5 minute, amestecând. Adaugă ardeiul și dovlecelul, roșiile pasate, foaia de dafin și un praf bun de sare, împreună cu un strop de apă. Acoperă și fierbe blând circa 30 de minute, amestecând din când în când, până fiecare legumă e fragedă, iar sosul e bogat. Trebuie să iasă o tocană moale, nu o supă — dacă e nevoie, mai fierbe câteva minute descoperit. Potrivește de gust și servește cald, simplu sau ca garnitură.',
      en:'Cut all the vegetables — potato, carrot, onion, bell pepper and zucchini — into similar bite-sized pieces so they cook evenly. Warm the oil in a wide pot and soften the onion and garlic for 4 minutes, then add the harder vegetables (potato and carrot) and cook for 5 minutes, stirring. Add the pepper and zucchini, the tomato passata, bay leaf and a good pinch of salt, along with a splash of water. Cover and simmer gently for about 30 minutes, stirring occasionally, until every vegetable is tender and the sauce is rich. It should end up soft and stewy, not soupy — cook uncovered for the last few minutes if needed. Season to taste and serve warm, on its own or as a side.',
      es:'Corta todas las verduras —patata, zanahoria, cebolla, pimiento y calabacín— en trozos de tamaño similar para que cuezan por igual. Calienta el aceite en una olla amplia y sofríe la cebolla y el ajo 4 minutos, luego añade las verduras más duras (patata y zanahoria) y cocina 5 minutos, removiendo. Añade el pimiento y el calabacín, el tomate, la hoja de laurel y una buena pizca de sal, junto con un chorrito de agua. Tapa y cuece suave unos 30 minutos, removiendo de vez en cuando, hasta que todas las verduras estén tiernas y la salsa sea densa. Debe quedar como un guiso blando, no una sopa —cuece destapado los últimos minutos si hace falta—. Ajusta de sal y sirve caliente, solo o como guarnición.',
      fr:'Coupez tous les légumes — pomme de terre, carotte, oignon, poivron et courgette — en morceaux de taille similaire pour une cuisson homogène. Chauffez l’huile dans une grande casserole et faites revenir l’oignon et l’ail 4 minutes, puis ajoutez les légumes les plus fermes (pomme de terre et carotte) et faites cuire 5 minutes en remuant. Ajoutez le poivron et la courgette, les tomates passées, la feuille de laurier et une bonne pincée de sel, avec un peu d’eau. Couvrez et laissez mijoter doucement environ 30 minutes, en remuant de temps en temps, jusqu’à ce que chaque légume soit tendre et la sauce riche. Cela doit rester un ragoût moelleux, pas une soupe — cuisez à découvert les dernières minutes si besoin. Rectifiez l’assaisonnement et servez chaud, seul ou en accompagnement.',
      de:'Alle Gemüse — Kartoffel, Karotte, Zwiebel, Paprika und Zucchini — in ähnlich große Stücke schneiden, damit sie gleichmäßig garen. Das Öl in einem weiten Topf erwärmen und Zwiebel und Knoblauch 4 Minuten anschwitzen, dann das festere Gemüse (Kartoffel und Karotte) zugeben und unter Rühren 5 Minuten braten. Paprika und Zucchini, passierte Tomaten, Lorbeerblatt und eine gute Prise Salz zugeben, dazu einen Schuss Wasser. Zudecken und etwa 30 Minuten sanft köcheln, gelegentlich rühren, bis jedes Gemüse weich und die Soße reichhaltig ist. Es soll ein weicher Eintopf werden, keine Suppe — die letzten Minuten bei Bedarf offen kochen. Abschmecken und warm servieren, pur oder als Beilage.',
      pt:'Corte todos os legumes — batata, cenoura, cebola, pimentão e courgette — em pedaços de tamanho semelhante para cozerem por igual. Aqueça o óleo numa panela larga e refogue a cebola e o alho 4 minutos, depois junte os legumes mais duros (batata e cenoura) e cozinhe 5 minutos, mexendo. Junte o pimentão e a courgette, o tomate passata, a folha de louro e uma boa pitada de sal, com um pouco de água. Tape e cozinhe brandamente cerca de 30 minutos, mexendo de vez em quando, até todos os legumes ficarem macios e o molho encorpado. Deve ficar um guisado macio, não uma sopa — coza destapado nos últimos minutos se precisar. Acerte o sal e sirva quente, simples ou como acompanhamento.',
      ru:'Нарежьте все овощи — картофель, морковь, лук, болгарский перец и кабачок — кусочками схожего размера, чтобы они готовились равномерно. Разогрейте масло в широкой кастрюле и обжарьте лук и чеснок 4 минуты, затем добавьте более твёрдые овощи (картофель и морковь) и готовьте 5 минут, помешивая. Добавьте перец и кабачок, протёртые томаты, лавровый лист и хорошую щепотку соли, а также немного воды. Накройте и тушите на слабом огне около 30 минут, изредка помешивая, пока все овощи не станут мягкими, а соус — насыщенным. Должно получиться мягкое рагу, а не суп — при необходимости последние минуты готовьте без крышки. Посолите по вкусу и подавайте тёплым, само по себе или как гарнир.',
      ar:'قطّع كل الخضار — البطاطس والجزر والبصل والفلفل الحلو والكوسة — إلى قطع متقاربة الحجم لتنضج بالتساوي. سخّن الزيت في قدر واسع وشوّح البصل والثوم 4 دقائق، ثم أضف الخضار الأقسى (البطاطس والجزر) واطهها 5 دقائق مع التقليب. أضف الفلفل والكوسة والطماطم المهروسة وورقة الغار ورشة ملح جيدة مع رشة ماء. غطِّ القدر واطهه بهدوء نحو 30 دقيقة مع التقليب أحياناً حتى تنضج كل الخضار وتصبح الصلصة غنية. يجب أن يكون يخنة طرية لا شوربة — اطهه مكشوفاً في الدقائق الأخيرة إن لزم. اضبط التتبيل وقدّمه دافئاً، وحده أو كطبق جانبي.',
      zh:'把所有蔬菜——土豆、胡萝卜、洋葱、甜椒和西葫芦——切成大小相近的块，方便均匀成熟。宽口锅热油，炒洋葱和蒜4分钟，再加较硬的蔬菜（土豆和胡萝卜）翻炒5分钟。加入甜椒、西葫芦、番茄泥、香叶和一大撮盐，再加少许水。加盖小火煮约30分钟，其间不时搅动，至所有蔬菜软烂、汤汁浓郁。成品应是软糯的炖菜而非汤——需要的话最后几分钟开盖收汁。按口味调味，趁热单吃或作配菜。',
      ja:'すべての野菜——じゃがいも、にんじん、玉ねぎ、パプリカ、ズッキーニ——を火通りがそろうよう同じくらいの一口大に切る。広めの鍋に油を温め、玉ねぎとにんにくを4分炒め、火の通りにくい野菜（じゃがいもとにんじん）を加えて混ぜながら5分炒める。パプリカとズッキーニ、トマトピューレ、ローリエ、塩ひとつまみを水少々とともに加える。ふたをして約30分、時々混ぜながら、すべての野菜が柔らかくソースが濃厚になるまで静かに煮る。スープではなく、柔らかい煮込みに仕上げる——必要なら最後の数分はふたを取って煮詰める。味を調え、そのまま、または付け合わせとして温かいうちに供する。',
      hi:'सभी सब्ज़ियाँ — आलू, गाजर, प्याज़, शिमला मिर्च और तोरी — एक जैसे टुकड़ों में काटें ताकि समान रूप से पकें। चौड़े बर्तन में तेल गरम करें और प्याज़ व लहसुन 4 मिनट भूनें, फिर सख्त सब्ज़ियाँ (आलू और गाजर) डालकर 5 मिनट चलाते हुए पकाएँ। शिमला मिर्च और तोरी, टमाटर प्यूरी, तेज पत्ता और अच्छी चुटकी नमक थोड़े पानी के साथ डालें। ढककर लगभग 30 मिनट धीमी आँच पर बीच-बीच में चलाते हुए पकाएँ जब तक हर सब्ज़ी नरम और सॉस गाढ़ी हो। यह नरम सालन जैसा बने, सूप नहीं — ज़रूरत हो तो आख़िरी कुछ मिनट खुला पकाएँ। स्वादानुसार नमक ठीक करें और गरम, अकेले या साइड के रूप में परोसें।',
      tr:'Bütün sebzeleri — patates, havuç, soğan, dolmalık biber ve kabak — eşit pişsin diye benzer büyüklükte lokmalara doğrayın. Geniş bir tencerede yağı ısıtın, soğan ve sarımsağı 4 dakika kavurun, sonra sert sebzeleri (patates ve havuç) ekleyip karıştırarak 5 dakika pişirin. Biber ve kabağı, domates püresini, defne yaprağını ve iyi bir tutam tuzu biraz suyla ekleyin. Kapağını kapatıp yaklaşık 30 dakika, ara sıra karıştırarak, tüm sebzeler yumuşayıp sos koyulaşana dek hafifçe pişirin. Çorba değil, yumuşak bir güveç olmalı — gerekirse son birkaç dakika kapaksız pişirin. Tuzunu ayarlayıp sıcak, tek başına ya da garnitür olarak servis edin.',
      it:'Taglia tutte le verdure — patata, carota, cipolla, peperone e zucchina — a pezzi di dimensioni simili così cuociono in modo uniforme. Scalda l’olio in una pentola ampia e fai appassire cipolla e aglio per 4 minuti, poi aggiungi le verdure più dure (patata e carota) e cuoci 5 minuti, mescolando. Aggiungi peperone e zucchina, la passata, l’alloro e una buona presa di sale, con un goccio d’acqua. Copri e fai sobbollire dolcemente circa 30 minuti, mescolando ogni tanto, finché ogni verdura è tenera e il sugo è ricco. Deve venire uno stufato morbido, non una minestra — cuoci scoperto gli ultimi minuti se serve. Regola di sale e servi caldo, da solo o come contorno.',
      ko:'모든 채소 — 감자, 당근, 양파, 파프리카, 애호박 — 를 고르게 익도록 비슷한 한입 크기로 썬다. 넓은 냄비에 기름을 데우고 양파와 마늘을 4분 볶은 뒤 단단한 채소(감자와 당근)를 넣어 저으며 5분 볶는다. 파프리카와 애호박, 토마토 퓌레, 월계수 잎, 소금 넉넉히 한 꼬집을 물 조금과 함께 넣는다. 뚜껑을 덮고 약 30분간 가끔 저으며 모든 채소가 부드럽고 소스가 진해질 때까지 은근히 끓인다. 수프가 아니라 부드러운 스튜가 되어야 한다 — 필요하면 마지막 몇 분은 뚜껑을 열고 졸인다. 간을 맞춰 그대로 또는 곁들임으로 따뜻하게 낸다.' } },
];

const recipes = SPECS.map(mk);

export { recipes };
export default recipes;
export const BUDGET_RECIPES = recipes;

if (typeof window !== 'undefined') {
  window.BUDGET_RECIPES = recipes;
}
